export function refundCredits(account, usedCredits) {
  if (usedCredits < 0) throw new RangeError('usedCredits must be non-negative');
  const refunded = Math.min(usedCredits, account.spentCredits);
  account.spentCredits -= refunded;
  account.availableCredits += refunded;
  return refunded;
}

